(() => {const progress=document.querySelector(".scroll-progress span");let ticking=false;function update(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+"%";ticking=false;}window.addEventListener("scroll",()=>{if(!ticking){requestAnimationFrame(update);ticking=true;}},{passive:true});update();const orb=document.querySelector(".hero-orb");if(orb&&!window.matchMedia("(prefers-reduced-motion: reduce)").matches){window.addEventListener("pointermove",e=>{const x=(e.clientX/innerWidth-.5)*9,y=(e.clientY/innerHeight-.5)*9;orb.style.transform="translate3d("+x+"px,"+y+"px,0)";},{passive:true});}})();